IF OBJECT_ID(N'dbo.schema_migrations', N'U') IS NULL
BEGIN
  CREATE TABLE dbo.schema_migrations (version int NOT NULL PRIMARY KEY, applied_utc datetime2(0) NOT NULL CONSTRAINT df_schema_migrations_applied DEFAULT SYSUTCDATETIME());
END;
IF NOT EXISTS (SELECT 1 FROM dbo.schema_migrations WHERE version = 1)
BEGIN
  CREATE TABLE dbo.facilities (facility_id int IDENTITY PRIMARY KEY, facility_code nvarchar(30) NOT NULL UNIQUE, facility_name nvarchar(120) NOT NULL);
  CREATE TABLE dbo.customers (customer_id int IDENTITY PRIMARY KEY, customer_code nvarchar(30) NOT NULL UNIQUE, customer_name nvarchar(120) NOT NULL UNIQUE);
  CREATE TABLE dbo.products (product_id int IDENTITY PRIMARY KEY, sku nvarchar(50) NOT NULL UNIQUE, product_name nvarchar(120) NOT NULL, uom nvarchar(20) NOT NULL);
  CREATE TABLE dbo.carriers (carrier_id int IDENTITY PRIMARY KEY, carrier_name nvarchar(120) NOT NULL UNIQUE);
  CREATE TABLE dbo.shipments (shipment_id nvarchar(30) PRIMARY KEY, customer_id int NOT NULL REFERENCES dbo.customers(customer_id), product_id int NOT NULL REFERENCES dbo.products(product_id), facility_id int NOT NULL REFERENCES dbo.facilities(facility_id), carrier_id int NOT NULL REFERENCES dbo.carriers(carrier_id), dock_code nvarchar(20) NOT NULL, appointment_utc datetime2(0) NOT NULL, planned_departure_utc datetime2(0) NOT NULL, actual_departure_utc datetime2(0) NULL, ordered_qty decimal(18,3) NOT NULL CHECK (ordered_qty > 0), shipped_qty decimal(18,3) NOT NULL CHECK (shipped_qty >= 0), freight_cost decimal(18,2) NOT NULL CHECK (freight_cost >= 0), status nvarchar(30) NOT NULL CHECK (status IN ('Scheduled','In Transit','Delivered','Exception','Cancelled')), row_version rowversion NOT NULL, created_utc datetime2(0) NOT NULL CONSTRAINT df_shipments_created DEFAULT SYSUTCDATETIME(), CONSTRAINT ck_shipments_shipped_qty CHECK (shipped_qty <= ordered_qty));
  CREATE INDEX ix_shipments_board ON dbo.shipments (planned_departure_utc, status) INCLUDE (customer_id, product_id, facility_id, shipped_qty, ordered_qty, freight_cost);
  CREATE TABLE dbo.shipment_lines (shipment_line_id bigint IDENTITY PRIMARY KEY, shipment_id nvarchar(30) NOT NULL REFERENCES dbo.shipments(shipment_id), product_id int NOT NULL REFERENCES dbo.products(product_id), ordered_qty decimal(18,3) NOT NULL, shipped_qty decimal(18,3) NOT NULL);
  CREATE TABLE dbo.dock_appointments (appointment_id bigint IDENTITY PRIMARY KEY, shipment_id nvarchar(30) NOT NULL REFERENCES dbo.shipments(shipment_id), dock_code nvarchar(20) NOT NULL, appointment_utc datetime2(0) NOT NULL, status nvarchar(30) NOT NULL);
  CREATE TABLE dbo.production_runs (production_run_id bigint IDENTITY PRIMARY KEY, facility_id int NOT NULL REFERENCES dbo.facilities(facility_id), product_id int NOT NULL REFERENCES dbo.products(product_id), run_date date NOT NULL, output_qty decimal(18,3) NOT NULL, labor_hours decimal(18,2) NOT NULL);
  CREATE TABLE dbo.vendors (vendor_id int IDENTITY PRIMARY KEY, vendor_name nvarchar(120) NOT NULL UNIQUE);
  CREATE TABLE dbo.purchase_requests (request_id nvarchar(30) PRIMARY KEY, requester nvarchar(120) NOT NULL, facility_id int NOT NULL REFERENCES dbo.facilities(facility_id), status nvarchar(30) NOT NULL CHECK (status IN ('Draft','Pending','Approved','Rejected')), comment nvarchar(500) NOT NULL DEFAULT N'', version_no int NOT NULL DEFAULT 1, created_utc datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME(), updated_utc datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME());
  CREATE TABLE dbo.purchase_request_lines (request_line_id bigint IDENTITY PRIMARY KEY, request_id nvarchar(30) NOT NULL REFERENCES dbo.purchase_requests(request_id), product_id int NOT NULL REFERENCES dbo.products(product_id), quantity decimal(18,3) NOT NULL CHECK (quantity > 0), unit_cost decimal(18,4) NOT NULL CHECK (unit_cost >= 0));
  CREATE TABLE dbo.identity_roles (principal nvarchar(200) PRIMARY KEY, role_name nvarchar(50) NOT NULL);
  CREATE TABLE dbo.audit_events (audit_event_id bigint IDENTITY PRIMARY KEY, actor nvarchar(200) NOT NULL, action_name nvarchar(120) NOT NULL, entity_type nvarchar(80) NOT NULL, entity_id nvarchar(80) NOT NULL, detail_json nvarchar(max) NOT NULL, occurred_utc datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME());
  CREATE TABLE dbo.import_runs (import_run_id bigint IDENTITY PRIMARY KEY, source_name nvarchar(255) NOT NULL, started_utc datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME(), completed_utc datetime2(0) NULL, applied_count int NOT NULL DEFAULT 0, rejected_count int NOT NULL DEFAULT 0, status nvarchar(30) NOT NULL);
  CREATE TABLE dbo.import_errors (import_error_id bigint IDENTITY PRIMARY KEY, import_run_id bigint NOT NULL REFERENCES dbo.import_runs(import_run_id), source_row_no int NOT NULL, error_message nvarchar(500) NOT NULL, raw_json nvarchar(max) NOT NULL);
  CREATE TABLE dbo.knowledge_documents (document_id int IDENTITY PRIMARY KEY, title nvarchar(200) NOT NULL, body nvarchar(max) NOT NULL, sensitivity nvarchar(30) NOT NULL DEFAULT 'internal');
  CREATE TABLE dbo.knowledge_document_roles (document_id int NOT NULL REFERENCES dbo.knowledge_documents(document_id), role_name nvarchar(50) NOT NULL, PRIMARY KEY (document_id, role_name));
  EXEC(N'CREATE VIEW dbo.v_shipment_board AS SELECT s.shipment_id, c.customer_name, p.product_name, f.facility_name, ca.carrier_name, s.dock_code, s.appointment_utc, s.planned_departure_utc, s.actual_departure_utc, s.ordered_qty, s.shipped_qty, s.freight_cost, s.status, s.row_version FROM dbo.shipments s JOIN dbo.customers c ON c.customer_id=s.customer_id JOIN dbo.products p ON p.product_id=s.product_id JOIN dbo.facilities f ON f.facility_id=s.facility_id JOIN dbo.carriers ca ON ca.carrier_id=s.carrier_id');
  INSERT dbo.schema_migrations(version) VALUES (1);
END;
